1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipNumber",
26	        expression = "java(owner.getCustomerCode() == null || owner.getRegistrationDate() == null ? null : owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
27	    @Mapping(target = "membershipTier",
28	        expression = "java(owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3 ? org.springframework.samples.petclinic.rest.dto.OwnerDto.MembershipTierEnum.GOLD : (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0 && owner.getEmail() != null && !owner.getEmail().isBlank() ? org.springframework.samples.petclinic.rest.dto.OwnerDto.MembershipTierEnum.SILVER : org.springframework.samples.petclinic.rest.dto.OwnerDto.MembershipTierEnum.BRONZE))")
29	    @Mapping(target = "locality",
30	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.Locality.of(owner.getCity()))")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    Owner toOwner(OwnerDto ownerDto);
34	
35	    @Mapping(target = "id", ignore = true)
36	    @Mapping(target = "pets", ignore = true)
37	    Owner toOwner(OwnerFieldsDto ownerDto);
38	
39	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
40	
41	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
42	
43	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
44	        OwnerPageDto ownerPageDto = new OwnerPageDto();
45	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
46	        ownerPageDto.setPage(ownerPage.getNumber());
47	        ownerPageDto.setSize(ownerPage.getSize());
48	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
49	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
50	        return ownerPageDto;
51	    }
52	}
