1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
14	
15	/**
16	 * Enforces the household rule on create. An owner sharing an existing owner's last name and
17	 * address (compared in the normalized address form, see {@link AddressNormalizer}) is a 409 Conflict — unless the
18	 * request opted in with {@code sharesHousehold} true. When it did opt in, the two are allowed to
19	 * share a household and are given the same stable {@code householdId}: it is stamped on the new
20	 * owner and on every existing member of that household. Runs after {@link BuildOwner}.
21	 */
22	public class CheckOwnerHouseholdUnique {
23	
24	    public void service(@Val Owner owner, @Val Boolean sharesHousehold,
25	            OwnerRepository ownerRepository) throws DuplicateHouseholdException {
26	        String lastName = key(owner.getLastName());
27	        String address = AddressNormalizer.normalize(owner.getAddress());
28	        List<Owner> household = new ArrayList<>();
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
31	                continue; // same record (e.g. re-save), not a conflict
32	            }
33	            if (lastName.equals(key(existing.getLastName()))
34	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
35	                household.add(existing);
36	            }
37	        }
38	        if (household.isEmpty()) {
39	            owner.setHouseholdSize(1); // a household of one: just this new owner
40	            return; // no existing owner at this last name + address
41	        }
42	        if (!Boolean.TRUE.equals(sharesHousehold)) {
43	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
44	        }
45	        // Explicitly allowed to share: assign the same stable household identifier to all members,
46	        // and record the household's size (existing members plus this new owner) on every member so
47	        // the derived membership tier reflects the household as it stands after this create.
48	        String householdId = householdId(lastName, address, household);
49	        int householdSize = household.size() + 1;
50	        owner.setHouseholdId(householdId);
51	        owner.setHouseholdSize(householdSize);
52	        for (Owner member : household) {
53	            member.setHouseholdId(householdId);
54	            member.setHouseholdSize(householdSize);
55	            ownerRepository.save(member);
56	        }
57	    }
58	
59	    /**
60	     * The household's stable shared identifier: reuse the id an existing member already carries
61	     * (so a household keeps one value over time); otherwise derive it deterministically from the
62	     * normalized last name and address, so independent joiners compute the same value.
63	     */
64	    private static String householdId(String lastName, String address, List<Owner> household) {
65	        for (Owner member : household) {
66	            String existing = member.getHouseholdId();
67	            if (existing != null && !existing.isBlank()) {
68	                return existing;
69	            }
70	        }
71	        return "H-" + sha256Hex(lastName + "\n" + address).substring(0, 12).toUpperCase(Locale.ROOT);
72	    }
73	
74	    private static String sha256Hex(String value) {
75	        try {
76	            byte[] digest = MessageDigest.getInstance("SHA-256")
77	                    .digest(value.getBytes(StandardCharsets.UTF_8));
78	            StringBuilder sb = new StringBuilder(digest.length * 2);
79	            for (byte b : digest) {
80	                sb.append(String.format("%02x", b));
81	            }
82	            return sb.toString();
83	        }
84	        catch (NoSuchAlgorithmException e) {
85	            throw new IllegalStateException("SHA-256 not available", e);
86	        }
87	    }
88	
89	    /** Comparison key: lower-cased, with leading/trailing and repeated whitespace collapsed. */
90	    private static String key(String value) {
91	        if (value == null) {
92	            return "";
93	        }
94	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
95	    }
96	}
